 94	export function computeCampaignMetrics(
 95	  candidates: Candidate[],
 96	  prev?: Partial<CampaignMetrics>,
 97	  /** Real elapsed hours from campaign creation to the first booked interview
 98	   *  (caller computes this from actual timestamps — see recomputeMetrics in
 99	   *  store.ts). `undefined` preserves whatever was already on `prev`; pass
100	   *  `null` explicitly once no booking exists yet. */
101	  timeToFirstInterviewHours?: number | null,
102	): CampaignMetrics {
103	  const sourced = candidates.length;
104	  const contacted = candidates.filter((c) => effectiveStageRank(c) >= 1).length;
105	  const replied = candidates.filter((c) => effectiveStageRank(c) >= 2).length;
106	  const interested = candidates.filter(
107	    (c) => effectiveStageRank(c) >= 3 && c.stage !== "Not Interested",
108	  ).length;
109	  const booked = candidates.filter((c) => effectiveStageRank(c) >= 4).length;
110	  const interviewed = candidates.filter((c) =>
111	    ["Interviewed", "Offer", "Hired"].includes(c.stage),
112	  ).length;
113	  const offer = candidates.filter((c) => ["Offer", "Hired"].includes(c.stage)).length;
114	  const hired = candidates.filter((c) => c.stage === "Hired").length;
115	  const notInterested = candidates.filter((c) => c.stage === "Not Interested").length;
116	  const scores = candidates.map((c) => c.matchScore).filter(Boolean);
117	  const avg = scores.length ? round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
118	
119	  return {
120	    sourced,
121	    contacted,
122	    replied,
123	    interested,
124	    booked,
125	    interviewed,
126	    offer,
127	    hired,
128	    notInterested,
129	    replyRate: contacted ? replied / contacted : 0,
130	    avgMatchScore: avg,
131	    timeToFirstInterviewHours:
132	      timeToFirstInterviewHours !== undefined
133	        ? timeToFirstInterviewHours
134	        : (prev?.timeToFirstInterviewHours ?? null),
135	    emailsSentToday: prev?.emailsSentToday ?? 0,
136	    linkedinSentToday: prev?.linkedinSentToday ?? 0,
137	  };
138	}
140	export interface GlobalKpis {
141	  activeCampaigns: number;
142	  totalCampaigns: number;
143	  candidatesSourced: number;
144	  contacted: number;
145	  replyRate: number;
146	  interviewsBooked: number;
147	  interested: number;
148	  awaitingBooking: number;
149	  avgMatchScore: number;
150	  timeToFirstInterviewHours: number | null;
151	  pendingApprovals: number;
152	  hotReplies: number;
153	}
154	
155	export function globalKpis(
156	  state: Pick<HermesState, "campaigns" | "candidates" | "outreach" | "replies">,
157	): GlobalKpis {
158	  const active = state.campaigns.filter((c) => !["Filled", "Paused"].includes(c.status));
159	  const cands = state.candidates;
160	  const contacted = cands.filter((c) => effectiveStageRank(c) >= 1).length;
161	  const replied = cands.filter((c) => effectiveStageRank(c) >= 2).length;
162	  const booked = cands.filter((c) => effectiveStageRank(c) >= 4).length;
163	  const interested = cands.filter(
164	    (c) => effectiveStageRank(c) >= 3 && c.stage !== "Not Interested",
165	  ).length;
166	  const awaitingBooking = cands.filter((c) => c.stage === "Interested" && !c.booking).length;
167	  const scores = cands.map((c) => c.matchScore).filter(Boolean);
168	  const avg = scores.length ? round(scores.reduce((a, b) => a + b, 0) / scores.length) : 0;
169	  // Mean time-to-first-interview across ACTIVE campaigns only.
170	  const ttfi = active
171	    .map((c) => c.metrics.timeToFirstInterviewHours)
172	    .filter((v): v is number => v != null);
173	
174	  return {
175	    activeCampaigns: active.length,
176	    totalCampaigns: state.campaigns.length,
177	    candidatesSourced: cands.length,
178	    contacted,
179	    replyRate: contacted ? replied / contacted : 0,
180	    interviewsBooked: booked,
181	    interested,
182	    awaitingBooking,
183	    avgMatchScore: avg,
184	    timeToFirstInterviewHours: ttfi.length ? round(ttfi.reduce((a, b) => a + b, 0) / ttfi.length) : null,
185	    pendingApprovals: state.outreach.filter(
186	      (m) => m.status === "Needs Approval" || m.status === "Pending Manual Send",
187	    ).length,
188	    hotReplies: state.replies.filter(
189	      (r) => !r.handled && ["INTERESTED", "QUALIFIED_INTEREST"].includes(r.intent),
190	    ).length,
191	  };
192	}

