 92	export async function DELETE(req: NextRequest) {
 93	  // Fail closed in production (middleware doesn't cover /api/*).
 94	  const prodBlock = prodFailClosed();
 95	  if (prodBlock) return prodBlock;
 96	
 97	  // Auth-first: authorise BEFORE validating input or returning anything.
 98	  let supabase: Awaited<ReturnType<typeof getServerSupabase>> = null;
 99	  if (supabaseEnabled) {
100	    supabase = await getServerSupabase();
101	    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
102	    const admin = await requireAdmin(supabase);
103	    if (!admin.ok) return admin.response;
104	  }
105	
106	  const limit = checkRateLimit(rateLimitKey(req, "keys-delete"), { windowMs: 60_000, max: 20 });
107	  if (!limit.ok) return tooManyRequests(limit.retryAfterSec);
108	
109	  const id = new URL(req.url).searchParams.get("id");
110	  if (!id || !z.string().uuid().safeParse(id).success) {
111	    return NextResponse.json({ ok: false, error: "Missing or invalid id." }, { status: 400 });
112	  }
113	
114	  if (!supabaseEnabled) return NextResponse.json({ ok: true, demo: true });
115	  if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
116	  const { error } = await supabase.from("api_keys").delete().eq("id", id);
117	  if (error) {
118	    safeLog("api_keys delete error", { message: error.message, code: error.code });
119	    return NextResponse.json({ ok: false, error: "Couldn't delete the key. Try again." }, { status: 403 });
120	  }
121	  return NextResponse.json({ ok: true });
122	}

